/**
 * Core PDF Compression Engine
 */
class CompressPdfEngine {
  /**
   * Format file size in human-readable bytes
   */
  static formatBytes(bytes) {
    if (bytes === 0) return "0 Bytes";
    const k = 1024;
    const sizes = ["Bytes", "KB", "MB", "GB"];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + " " + sizes[i];
  }

  /**
   * Validate uploaded PDF file candidate
   */
  static validatePdfFile(file) {
    if (!file) {
      return { valid: false, error: "No file selected." };
    }
    if (file.size === 0) {
      return { valid: false, error: `File "${file.name}" is empty (0 bytes).` };
    }

    const name = file.name || "";
    const isPdfExt = name.toLowerCase().endsWith(".pdf");
    const isPdfMime = file.type === "application/pdf" || file.type === "";

    if (!isPdfExt && !isPdfMime) {
      return {
        valid: false,
        error: `"${file.name}" is not a valid PDF document.`,
      };
    }

    return { valid: true };
  }

  /**
   * Perform Client-Side PDF Compression
   * @param {File} pdfFile Source PDF File
   * @param {string} level 'balanced' | 'high' | 'low'
   * @param {Object} options Configuration options
   * @param {Function} progressCallback Progress reporter
   */
  async compress(
    pdfFile,
    level = "balanced",
    options = {},
    progressCallback = null,
  ) {
    if (!window.PDFLib) {
      throw new Error(
        "PDF-Lib library is not loaded. Please refresh the page and try again.",
      );
    }

    const { PDFDocument } = window.PDFLib;
    const originalSize = pdfFile.size;

    if (progressCallback)
      progressCallback(10, "Reading PDF document streams...");
    const arrayBuffer = await pdfFile.arrayBuffer();

    // Verify PDF header
    const headerBytes = new Uint8Array(arrayBuffer.slice(0, 5));
    const headerStr = String.fromCharCode.apply(null, headerBytes);
    if (headerStr !== "%PDF-") {
      throw new Error(
        `"${pdfFile.name}" does not appear to be a valid, uncorrupted PDF document.`,
      );
    }

    let sourceDoc;
    try {
      sourceDoc = await PDFDocument.load(arrayBuffer, {
        ignoreEncryption: true,
      });
    } catch (err) {
      throw new Error(`Failed to parse PDF document: ${err.message}`);
    }

    const pageCount = sourceDoc.getPageCount();
    if (pageCount === 0) {
      throw new Error("The PDF document contains no pages.");
    }

    if (progressCallback)
      progressCallback(20, "Cleaning metadata & repacking stream objects...");

    // Create fresh document & copy pages (strips orphaned objects, unneeded metadata & bloated histories)
    const newDoc = await PDFDocument.create();
    const pageIndices = Array.from({ length: pageCount }, (_, i) => i);
    const copiedPages = await newDoc.copyPages(sourceDoc, pageIndices);

    for (let i = 0; i < copiedPages.length; i++) {
      newDoc.addPage(copiedPages[i]);
      if (progressCallback) {
        const pct = Math.round(20 + ((i + 1) / pageCount) * 15);
        progressCallback(
          pct,
          `Optimizing page resources ${i + 1} of ${pageCount}...`,
        );
      }
    }

    if (progressCallback)
      progressCallback(35, "Analyzing embedded image resources...");

    let totalImagesFound = 0;
    let optimizedImagesCount = 0;

    try {
      const imgResult = await this.optimizeEmbeddedImages(
        newDoc,
        level,
        progressCallback,
      );
      totalImagesFound = imgResult.total;
      optimizedImagesCount = imgResult.optimized;
    } catch (err) {}

    if (progressCallback)
      progressCallback(80, "Applying object stream Flate-compression...");

    // Save with useObjectStreams: true to compress object streams, remove unused structures & duplicate fonts
    const compressedBytes = await newDoc.save({ useObjectStreams: true });

    if (progressCallback)
      progressCallback(95, "Finalizing compressed document metrics...");

    let finalBytes = compressedBytes;
    let finalSize = compressedBytes.length;

    // Safety check: If compressed file ended up larger than original, default to standard object stream save or original
    if (finalSize >= originalSize && compressedBytes !== arrayBuffer) {
      finalBytes = new Uint8Array(arrayBuffer);
      finalSize = originalSize;
    }

    const savedBytes = Math.max(0, originalSize - finalSize);
    const savedPercent =
      originalSize > 0 ? Math.round((savedBytes / originalSize) * 100) : 0;

    // Automatically detect if PDF mostly contains vector graphics or text and cannot be compressed significantly
    const isHighlyOptimized =
      (totalImagesFound === 0 || optimizedImagesCount === 0) &&
      savedPercent < 8;

    const blob = new Blob([finalBytes], { type: "application/pdf" });
    const blobUrl = URL.createObjectURL(blob);

    return {
      blob,
      blobUrl,
      originalSize,
      newSize: finalSize,
      savedBytes,
      savedPercent,
      pageCount,
      totalImagesFound,
      optimizedImagesCount,
      isHighlyOptimized,
    };
  }

  /**
   * Deep Embedded Image Optimization
   * Loops through all PDF objects, extracts image XObjects, downscales and re-compresses them using HTML5 Canvas.
   */
  async optimizeEmbeddedImages(pdfDoc, level, progressCallback) {
    const { PDFName, PDFRawStream, PDFNumber } = window.PDFLib;
    const context = pdfDoc.context;
    const indirectObjects = context.enumerateIndirectObjects();

    const imageRefs = [];

    for (const [ref, obj] of indirectObjects) {
      if (
        obj &&
        (obj instanceof PDFRawStream ||
          obj.constructor?.name === "PDFRawStream")
      ) {
        const subtype = obj.dict.get(PDFName.of("Subtype"));
        if (subtype && subtype.toString() === "/Image") {
          imageRefs.push({ ref, obj });
        }
      }
    }

    const total = imageRefs.length;
    let optimized = 0;

    if (total === 0) {
      return { total: 0, optimized: 0 };
    }

    for (let idx = 0; idx < total; idx++) {
      const { ref, obj } = imageRefs[idx];

      if (progressCallback) {
        const pct = Math.round(35 + (idx / total) * 45);
        progressCallback(
          pct,
          `Compressing image resource ${idx + 1} of ${total}...`,
        );
      }

      try {
        const bytes = obj.getUncompressedContents();
        if (!bytes || bytes.length < 5120) {
          // Skip tiny images/icons (< 5KB)
          continue;
        }

        // Check image header signature
        const isJpeg =
          bytes[0] === 0xff && bytes[1] === 0xd8 && bytes[2] === 0xff;
        const isPng =
          bytes[0] === 0x89 &&
          bytes[1] === 0x50 &&
          bytes[2] === 0x4e &&
          bytes[3] === 0x47;
        const isGif =
          bytes[0] === 0x47 && bytes[1] === 0x49 && bytes[2] === 0x46;

        const filter = obj.dict.get(PDFName.of("Filter"));
        const filterStr = filter ? filter.toString() : "";
        const isMaybeJpeg = isJpeg || filterStr.includes("DCTDecode");

        if (
          !isMaybeJpeg &&
          !isPng &&
          !isGif &&
          !filterStr.includes("FlateDecode")
        ) {
          continue;
        }

        let mimeType = "image/jpeg";
        if (isPng) mimeType = "image/png";
        else if (isGif) mimeType = "image/gif";
        else if (filterStr.includes("FlateDecode")) mimeType = "image/png";

        const blob = new Blob([bytes], { type: mimeType });
        const imgUrl = URL.createObjectURL(blob);

        const img = await new Promise((resolve, reject) => {
          const image = new Image();
          image.onload = () => {
            URL.revokeObjectURL(imgUrl);
            resolve(image);
          };
          image.onerror = (err) => {
            URL.revokeObjectURL(imgUrl);
            reject(err);
          };
          image.src = imgUrl;
        }).catch(() => null);

        if (!img || img.width <= 64 || img.height <= 64) {
          continue;
        }

        // Compression presets & downscaling limits
        let scale = 1.0;
        let quality = 0.75;
        let maxDimension = 1600;

        if (level === "low") {
          scale = 0.85;
          quality = 0.85;
          maxDimension = 1600;
        } else if (level === "balanced") {
          scale = 0.7;
          quality = 0.7;
          maxDimension = 1200;
        } else if (level === "high") {
          scale = 0.5;
          quality = 0.5;
          maxDimension = 800;
        }

        let newWidth = img.width * scale;
        let newHeight = img.height * scale;

        if (newWidth > maxDimension || newHeight > maxDimension) {
          const ratio = Math.min(
            maxDimension / newWidth,
            maxDimension / newHeight,
          );
          newWidth = newWidth * ratio;
          newHeight = newHeight * ratio;
        }

        const width = Math.max(1, Math.round(newWidth));
        const height = Math.max(1, Math.round(newHeight));

        const canvas = document.createElement("canvas");
        canvas.width = width;
        canvas.height = height;
        const ctx = canvas.getContext("2d");

        const hasAlpha = isPng || filterStr.includes("SMask");
        if (!hasAlpha) {
          ctx.fillStyle = "#FFFFFF";
          ctx.fillRect(0, 0, width, height);
        }

        ctx.drawImage(img, 0, 0, width, height);

        // Re-encode images using Canvas/WebP/JPEG depending on content:
        // JPEG offers maximum savings for complex color gradients, PNG for transparency.
        let targetMime = "image/jpeg";
        let targetFilter = "DCTDecode";

        if (hasAlpha) {
          targetMime = "image/png";
          targetFilter = "FlateDecode";
        } else {
          targetMime = "image/jpeg";
          targetFilter = "DCTDecode";
        }

        const compressedBlob = await new Promise((resolve) =>
          canvas.toBlob(resolve, targetMime, quality),
        );
        const compressedBuffer = await compressedBlob.arrayBuffer();
        const compressedBytes = new Uint8Array(compressedBuffer);

        if (compressedBytes.length < bytes.length) {
          obj.dict.set(PDFName.of("Filter"), PDFName.of(targetFilter));
          obj.dict.set(PDFName.of("Width"), PDFNumber.of(width));
          obj.dict.set(PDFName.of("Height"), PDFNumber.of(height));
          obj.dict.delete(PDFName.of("DecodeParms"));

          const newStream = PDFRawStream.of(obj.dict, compressedBytes);
          context.register(ref, newStream);
          optimized++;
        }
      } catch (imageErr) {}
    }

    return { total, optimized };
  }
}

/**
 * UI Controller for Compress PDF Application
 */
document.addEventListener("DOMContentLoaded", () => {
  // Application State
  const state = {
    pdfFile: null,
    pageCount: 1,
    selectedLevel: "balanced", // 'balanced' | 'high' | 'low'
  };

  // DOM Elements
  const dropzone = document.getElementById("compress-dropzone");
  const fileInput = document.getElementById("compress-file-input");
  const chooseBtn = dropzone
    ? dropzone.querySelector(".file-uploader__choose-btn")
    : null;

  const uploadSection = document.getElementById("compress-upload-section");
  const workspaceSection = document.getElementById(
    "compress-workspace-section",
  );
  const processingState = document.getElementById("compress-processing-state");
  const resultSection = document.getElementById("compress-result-section");

  const filenameDisplay = document.getElementById("compress-filename-display");
  const filemetaDisplay = document.getElementById("compress-filemeta-display");
  const btnChangePdf = document.getElementById("btn-change-pdf");

  const optionCards = document.querySelectorAll(".compress-option-card");
  const outputFilenameInput = document.getElementById("output-filename-input");
  const btnExecuteCompress = document.getElementById("btn-execute-compress");

  // Stats Elements
  const statOrigSize = document.getElementById("stat-orig-size");
  const statNewSize = document.getElementById("stat-new-size");
  const statSavingsText = document.getElementById("stat-savings-text");
  const statSavingsPct = document.getElementById("stat-savings-pct");
  const statBadgePct = document.getElementById("stat-badge-pct");

  const resultFilenameDisplay = document.getElementById(
    "result-filename-display",
  );
  const resultMetaDisplay = document.getElementById("result-meta-display");
  const btnDownloadCompressed = document.getElementById(
    "btn-download-compressed",
  );
  const btnStartOver = document.getElementById("btn-compress-start-over");

  /* ==========================================
     FILE UPLOAD & DRAG DROP HANDLERS
     ========================================== */
  if (chooseBtn && fileInput) {
    chooseBtn.addEventListener("click", (e) => {
      e.stopPropagation();
      e.preventDefault();
      fileInput.click();
    });
  }

  if (dropzone) {
    dropzone.addEventListener("click", (e) => {
      if (e.target.closest("#compress-file-input")) return;
      fileInput.click();
    });

    ["dragenter", "dragover"].forEach((eventName) => {
      dropzone.addEventListener(eventName, (e) => {
        e.preventDefault();
        e.stopPropagation();
        dropzone.classList.add("file-uploader__dropzone--active");
      });
    });

    ["dragleave", "drop"].forEach((eventName) => {
      dropzone.addEventListener(eventName, (e) => {
        e.preventDefault();
        e.stopPropagation();
        dropzone.classList.remove("file-uploader__dropzone--active");
      });
    });

    dropzone.addEventListener("drop", (e) => {
      const dt = e.dataTransfer;
      if (dt && dt.files && dt.files.length > 0) {
        handleFileSelection(dt.files[0]);
      }
    });
  }

  if (fileInput) {
    fileInput.addEventListener("change", (e) => {
      if (e.target.files && e.target.files.length > 0) {
        handleFileSelection(e.target.files[0]);
      }
    });
  }

  if (btnChangePdf) {
    btnChangePdf.addEventListener("click", () => {
      resetToUploadState();
    });
  }

  /* ==========================================
     FILE SELECTION & VALIDATION
     ========================================== */
  async function handleFileSelection(file) {
    const val = CompressPdfEngine.validatePdfFile(file);
    if (!val.valid) {
      showCompressToast(val.error, "error", "Invalid File");
      return;
    }

    try {
      state.pdfFile = file;
      filenameDisplay.textContent = file.name;
      filemetaDisplay.textContent = `Original Size: ${CompressPdfEngine.formatBytes(file.size)} • Reading pages...`;

      // Set output filename default
      const baseName = file.name.replace(/\.[^/.]+$/, "");
      if (outputFilenameInput) {
        outputFilenameInput.value = `${baseName}-compressed.pdf`;
      }

      // Read page count via PDF.js if available
      const arrayBuffer = await file.arrayBuffer();
      if (window.pdfjsLib) {
        const doc = await pdfjsLib.getDocument({ data: arrayBuffer }).promise;
        state.pageCount = doc.numPages;
        filemetaDisplay.textContent = `Original Size: ${CompressPdfEngine.formatBytes(file.size)} • ${state.pageCount} page${state.pageCount > 1 ? "s" : ""}`;
      } else {
        filemetaDisplay.textContent = `Original Size: ${CompressPdfEngine.formatBytes(file.size)}`;
      }

      // Hide upload area, reveal workspace
      uploadSection.style.display = "none";
      workspaceSection.style.display = "block";

      showCompressToast(
        `Loaded "${file.name}" successfully.`,
        "success",
        "PDF Ready",
      );
    } catch (err) {
      console.error(err);
      showCompressToast(
        `Could not process PDF file: ${err.message}`,
        "error",
        "Error Loading PDF",
      );
      resetToUploadState();
    }
  }

  /* ==========================================
     COMPRESSION OPTION CARDS SELECTION
     ========================================== */
  optionCards.forEach((card) => {
    card.addEventListener("click", () => {
      const level = card.getAttribute("data-level");
      if (!level) return;

      state.selectedLevel = level;

      optionCards.forEach((c) => {
        c.classList.remove("active");
        c.style.border = "1px solid var(--border-subtle)";
        c.style.background = "var(--bg-surface)";
        const radio = c.querySelector('input[type="radio"]');
        if (radio) radio.checked = false;
      });

      card.classList.add("active");
      card.style.border = "2px solid var(--primary)";
      card.style.background = "rgba(99, 102, 241, 0.04)";
      const currentRadio = card.querySelector('input[type="radio"]');
      if (currentRadio) currentRadio.checked = true;
    });
  });

  /* ==========================================
     EXECUTE COMPRESSION & DOWNLOAD
     ========================================== */
  if (btnExecuteCompress) {
    btnExecuteCompress.addEventListener("click", async () => {
      if (!state.pdfFile) {
        showCompressToast("Please upload a PDF file first.", "error");
        return;
      }

      try {
        workspaceSection.style.display = "none";
        processingState.style.display = "block";

        const progressFill = document.getElementById("compress-progress-fill");
        const statusDesc = document.getElementById("compress-status-desc");

        const engine = new CompressPdfEngine();

        const result = await engine.compress(
          state.pdfFile,
          state.selectedLevel,
          {},
          (pct, msg) => {
            if (progressFill) progressFill.style.width = `${pct}%`;
            if (statusDesc) statusDesc.textContent = msg;
          },
        );

        // Populate comparison statistics
        const origFmt = CompressPdfEngine.formatBytes(result.originalSize);
        const newFmt = CompressPdfEngine.formatBytes(result.newSize);
        const savedFmt = CompressPdfEngine.formatBytes(result.savedBytes);

        if (statOrigSize) statOrigSize.textContent = origFmt;
        if (statNewSize) statNewSize.textContent = newFmt;

        // Toggle optimization warning message
        const warningEl = document.getElementById("stat-optimization-warning");
        if (warningEl) {
          if (result.isHighlyOptimized) {
            warningEl.style.display = "flex";
          } else {
            warningEl.style.display = "none";
          }
        }

        if (result.savedBytes > 0) {
          if (statSavingsText)
            statSavingsText.textContent = `${savedFmt} Saved`;
          if (statSavingsPct)
            statSavingsPct.textContent = `${result.savedPercent}% smaller file size`;
          if (statBadgePct) {
            statBadgePct.textContent = `-${result.savedPercent}%`;
            statBadgePct.style.background = "rgba(16, 185, 129, 0.12)";
            statBadgePct.style.color = "var(--success)";
          }
        } else {
          if (statSavingsText)
            statSavingsText.textContent = `Maximally Optimized`;
          if (statSavingsPct)
            statSavingsPct.textContent = `Document is already at optimal size`;
          if (statBadgePct) {
            statBadgePct.textContent = `0% Change`;
            statBadgePct.style.background = "rgba(99, 102, 241, 0.12)";
            statBadgePct.style.color = "var(--primary)";
          }
        }

        // Set result filename and download link
        const outName =
          (outputFilenameInput ? outputFilenameInput.value.trim() : "") ||
          "compressed-document.pdf";
        if (resultFilenameDisplay) resultFilenameDisplay.textContent = outName;
        if (resultMetaDisplay)
          resultMetaDisplay.textContent = `${newFmt} • ${result.pageCount} page${result.pageCount > 1 ? "s" : ""}`;

        if (btnDownloadCompressed) {
          btnDownloadCompressed.href = result.blobUrl;
          btnDownloadCompressed.download = outName;
        }

        processingState.style.display = "none";
        resultSection.style.display = "block";

        showCompressToast("PDF compressed successfully!", "success", "Done");
      } catch (err) {
        console.error(err);
        showCompressToast(
          `Compression failed: ${err.message}`,
          "error",
          "Processing Error",
        );
        processingState.style.display = "none";
        workspaceSection.style.display = "block";
      }
    });
  }

  if (btnStartOver) {
    btnStartOver.addEventListener("click", () => {
      resetToUploadState();
    });
  }

  function resetToUploadState() {
    state.pdfFile = null;
    state.pageCount = 1;
    state.selectedLevel = "balanced";

    if (fileInput) fileInput.value = "";

    // Reset warning element
    const warningEl = document.getElementById("stat-optimization-warning");
    if (warningEl) {
      warningEl.style.display = "none";
    }

    // Reset option cards to balanced
    optionCards.forEach((c) => {
      const level = c.getAttribute("data-level");
      const radio = c.querySelector('input[type="radio"]');
      if (level === "balanced") {
        c.classList.add("active");
        c.style.border = "2px solid var(--primary)";
        c.style.background = "rgba(99, 102, 241, 0.04)";
        if (radio) radio.checked = true;
      } else {
        c.classList.remove("active");
        c.style.border = "1px solid var(--border-subtle)";
        c.style.background = "var(--bg-surface)";
        if (radio) radio.checked = false;
      }
    });

    workspaceSection.style.display = "none";
    processingState.style.display = "none";
    resultSection.style.display = "none";
    uploadSection.style.display = "block";
  }
});

/**
 * Comprexa - Extract PDF Pages Tool Controller
 * Fresh, production-ready, client-side PDF page extraction module.
 * Completely rebuilt from scratch.
 */

// Helper Toast function
function showExtractToast(message, type = "info", title = "") {
  if (
    window.ComprexaToast &&
    typeof window.ComprexaToast[type] === "function"
  ) {
    window.ComprexaToast[type](message, title);
  } else {
  }
}

/**
 * Processing Engine for Extract PDF Pages
 */
class ExtractPdfEngine {
  static formatBytes(bytes) {
    if (!bytes || bytes === 0) return "0 Bytes";
    const k = 1024;
    const sizes = ["Bytes", "KB", "MB", "GB"];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + " " + sizes[i];
  }

  static validateFile(file) {
    if (!file) {
      return { valid: false, error: "No file selected." };
    }
    if (file.size === 0) {
      return { valid: false, error: `File "${file.name}" is empty (0 bytes).` };
    }
    const name = file.name || "";
    const isPdfExt = name.toLowerCase().endsWith(".pdf");
    const isPdfMime = file.type === "application/pdf" || file.type === "";

    if (!isPdfExt && !isPdfMime) {
      return { valid: false, error: `"${file.name}" is not a valid PDF file.` };
    }
    return { valid: true };
  }

  /**
   * Parse user page range string (e.g., "1-5, 7, 9-12") into sorted array of unique 0-based page indices
   */
  static parsePageRange(rangeStr, totalPages) {
    if (!rangeStr || !rangeStr.trim()) return [];

    const tokens = rangeStr
      .split(",")
      .map((s) => s.trim())
      .filter(Boolean);
    const pageIndices = new Set();

    for (const token of tokens) {
      const match = token.match(/^(\d+)(?:\s*-\s*(\d+))?$/);
      if (!match) {
        throw new Error(
          `Invalid page range or number: "${token}". Use formats like "1-5" or "3".`,
        );
      }

      const start = parseInt(match[1], 10);
      const end = match[2] ? parseInt(match[2], 10) : start;

      if (isNaN(start) || isNaN(end)) {
        throw new Error(`Invalid page numbers in "${token}".`);
      }

      if (start < 1 || end < 1) {
        throw new Error(
          `Page numbers must be 1 or greater (found "${token}").`,
        );
      }

      if (start > end) {
        throw new Error(
          `Range start (${start}) cannot be greater than end (${end}) in "${token}".`,
        );
      }

      if (end > totalPages) {
        throw new Error(
          `Page ${end} exceeds total document pages (${totalPages}).`,
        );
      }

      for (let p = start; p <= end; p++) {
        pageIndices.add(p - 1); // convert 1-based page number to 0-based index
      }
    }

    return Array.from(pageIndices).sort((a, b) => a - b);
  }

  /**
   * Format array of 0-based indices into clean range string (e.g. "1-5, 7, 9-12")
   */
  static formatIndicesToRange(indices) {
    if (!indices || indices.length === 0) return "";

    const sorted = Array.from(new Set(indices))
      .sort((a, b) => a - b)
      .map((i) => i + 1); // convert to 1-based
    const ranges = [];
    let start = sorted[0];
    let prev = start;

    for (let i = 1; i < sorted.length; i++) {
      const current = sorted[i];
      if (current === prev + 1) {
        prev = current;
      } else {
        ranges.push(start === prev ? `${start}` : `${start}-${prev}`);
        start = current;
        prev = current;
      }
    }
    ranges.push(start === prev ? `${start}` : `${start}-${prev}`);
    return ranges.join(", ");
  }

  async loadPdfMetadata(file) {
    if (!window.PDFLib) {
      throw new Error(
        "PDF processing library (PDF-Lib) is not loaded. Please refresh the page.",
      );
    }

    const arrayBuffer = await file.arrayBuffer();
    const { PDFDocument } = window.PDFLib;

    const headerBytes = new Uint8Array(arrayBuffer.slice(0, 5));
    const headerStr = String.fromCharCode.apply(null, headerBytes);
    if (headerStr !== "%PDF-") {
      throw new Error(
        `"${file.name}" is not a valid, uncorrupted PDF document.`,
      );
    }

    let pdfLibDoc;
    try {
      pdfLibDoc = await PDFDocument.load(arrayBuffer, {
        ignoreEncryption: true,
      });
    } catch (err) {
      throw new Error(
        `Failed to parse "${file.name}". The document may be password-protected or corrupted.`,
      );
    }

    if (pdfLibDoc.isEncrypted) {
      throw new Error(
        `"${file.name}" is password-protected. Please remove encryption before modifying.`,
      );
    }

    const pageCount = pdfLibDoc.getPageCount();
    if (pageCount === 0) {
      throw new Error(`"${file.name}" contains no readable pages.`);
    }

    return {
      pdfLibDoc,
      arrayBuffer,
      pageCount,
      name: file.name,
      size: file.size,
      formattedSize: ExtractPdfEngine.formatBytes(file.size),
    };
  }

  async extractPages(
    file,
    arrayBuffer,
    selectedIndices,
    progressCallback = null,
  ) {
    if (!window.PDFLib) {
      throw new Error("PDF processing library is not loaded.");
    }

    const { PDFDocument } = window.PDFLib;
    const pdfDoc = await PDFDocument.load(arrayBuffer, {
      ignoreEncryption: true,
    });
    const totalPages = pdfDoc.getPageCount();

    if (!selectedIndices || selectedIndices.length === 0) {
      throw new Error("Please select at least one page to extract.");
    }

    for (const idx of selectedIndices) {
      if (idx < 0 || idx >= totalPages) {
        throw new Error(
          `Page ${idx + 1} is out of bounds for this document (${totalPages} total pages).`,
        );
      }
    }

    if (progressCallback) progressCallback(30, "Copying selected pages...");

    const newDoc = await PDFDocument.create();
    const copiedPages = await newDoc.copyPages(pdfDoc, selectedIndices);
    copiedPages.forEach((p) => newDoc.addPage(p));

    if (progressCallback) progressCallback(70, "Building new PDF file...");

    const pdfBytes = await newDoc.save();
    const blob = new Blob([pdfBytes], { type: "application/pdf" });
    const url = URL.createObjectURL(blob);

    const baseName = file.name.replace(/\.[^/.]+$/, "");
    const filename = `${baseName}-extracted.pdf`;

    return {
      blob,
      url,
      filename,
      originalPageCount: totalPages,
      extractedCount: selectedIndices.length,
      size: blob.size,
      formattedSize: ExtractPdfEngine.formatBytes(blob.size),
    };
  }
}

/**
 * UI Controller for Extract PDF Pages Tool
 */
class ExtractPdfUI {
  constructor() {
    this.engine = new ExtractPdfEngine();
    this.currentFile = null;
    this.arrayBuffer = null;
    this.pdfMeta = null;
    this.pdfJsDoc = null;

    // Page state: array of { pageNum: 1, index: 0, selectedForExtract: false }
    this.pages = [];
    this.createdBlobUrl = null;

    this.init();
  }

  init() {
    if (typeof document === "undefined") return;

    if (document.readyState === "loading") {
      document.addEventListener("DOMContentLoaded", () => this.bindDOM());
    } else {
      this.bindDOM();
    }
  }

  bindDOM() {
    this.uploadSection = document.getElementById("extract-upload-section");
    this.dropzone = document.getElementById("extract-dropzone");
    this.fileInput = document.getElementById("extract-file-input");

    this.fileInfoCard = document.getElementById("extract-file-info");
    this.filenameDisplay = document.getElementById("extract-filename-display");
    this.filesizeDisplay = document.getElementById("extract-filesize-display");
    this.btnChangePdf = document.getElementById("btn-change-extract-pdf");

    this.workspaceSection = document.getElementById(
      "extract-workspace-section",
    );
    this.rangeInput = document.getElementById("extract-range-input");
    this.btnApplyRange = document.getElementById("btn-apply-range");
    this.selectionBadge = document.getElementById("extract-selection-badge");
    this.btnSelectAll = document.getElementById("btn-select-all-extract");
    this.btnDeselectAll = document.getElementById("btn-deselect-all-extract");
    this.btnExecuteExtract = document.getElementById("btn-execute-extract");
    this.pagesGrid = document.getElementById("extract-pages-grid");

    this.processingState = document.getElementById("extract-processing-state");
    this.progressBar = document.getElementById("extract-progress-bar");

    this.resultSection = document.getElementById("extract-result-section");
    this.resultSummary = document.getElementById("extract-result-summary");
    this.btnDownloadPdf = document.getElementById("btn-download-extract-pdf");
    this.btnReset = document.getElementById("btn-reset-extract");

    this.bindEvents();
  }

  bindEvents() {
    // Dropzone & File Input
    if (this.dropzone && this.fileInput) {
      const chooseBtn = this.dropzone.querySelector(
        ".file-uploader__choose-btn",
      );
      if (chooseBtn) {
        chooseBtn.addEventListener("click", (e) => {
          e.stopPropagation();
          this.fileInput.click();
        });
      }

      this.dropzone.addEventListener("click", () => this.fileInput.click());
      this.dropzone.addEventListener("keydown", (e) => {
        if (e.key === "Enter" || e.key === " ") {
          e.preventDefault();
          this.fileInput.click();
        }
      });

      this.fileInput.addEventListener("change", (e) => {
        if (e.target.files && e.target.files.length > 0) {
          this.handleFileSelected(e.target.files[0]);
          this.fileInput.value = "";
        }
      });

      // Drag & Drop
      ["dragenter", "dragover"].forEach((evt) => {
        this.dropzone.addEventListener(evt, (e) => {
          e.preventDefault();
          e.stopPropagation();
          this.dropzone.classList.add("file-uploader__dropzone--active");
        });
      });

      ["dragleave", "drop"].forEach((evt) => {
        this.dropzone.addEventListener(evt, (e) => {
          e.preventDefault();
          e.stopPropagation();
          this.dropzone.classList.remove("file-uploader__dropzone--active");
        });
      });

      this.dropzone.addEventListener("drop", (e) => {
        const files = e.dataTransfer ? e.dataTransfer.files : null;
        if (files && files.length > 0) {
          const pdfFile = Array.from(files).find(
            (f) =>
              f.type === "application/pdf" ||
              f.name.toLowerCase().endsWith(".pdf"),
          );
          if (pdfFile) {
            this.handleFileSelected(pdfFile);
          } else {
            showExtractToast(
              "Please drop a valid PDF file.",
              "error",
              "Invalid File",
            );
          }
        }
      });
    }

    // Change PDF Button
    if (this.btnChangePdf) {
      this.btnChangePdf.addEventListener("click", () => {
        if (this.fileInput) this.fileInput.click();
      });
    }

    // Range Input Events
    if (this.btnApplyRange) {
      this.btnApplyRange.addEventListener("click", () =>
        this.applyRangeInput(),
      );
    }
    if (this.rangeInput) {
      this.rangeInput.addEventListener("keydown", (e) => {
        if (e.key === "Enter") {
          e.preventDefault();
          this.applyRangeInput();
        }
      });
      this.rangeInput.addEventListener("change", () => this.applyRangeInput());
    }

    // Selection Controls
    if (this.btnSelectAll) {
      this.btnSelectAll.addEventListener("click", () => this.selectAll());
    }
    if (this.btnDeselectAll) {
      this.btnDeselectAll.addEventListener("click", () => this.deselectAll());
    }

    // Execute Extract Action
    if (this.btnExecuteExtract) {
      this.btnExecuteExtract.addEventListener("click", () =>
        this.executeExtract(),
      );
    }

    // Reset View
    if (this.btnReset) {
      this.btnReset.addEventListener("click", () => this.resetView());
    }
  }

  async handleFileSelected(file) {
    const validation = ExtractPdfEngine.validateFile(file);
    if (!validation.valid) {
      showExtractToast(validation.error, "error", "Invalid File");
      return;
    }

    showExtractToast(`Loading "${file.name}"...`, "info", "Reading PDF");

    try {
      const meta = await this.engine.loadPdfMetadata(file);

      this.currentFile = file;
      this.arrayBuffer = meta.arrayBuffer;
      this.pdfMeta = meta;

      // Build pages state (default page 1 selected)
      this.pages = [];
      for (let i = 0; i < meta.pageCount; i++) {
        this.pages.push({
          pageNum: i + 1,
          index: i,
          selectedForExtract: i === 0, // Default first page selected
        });
      }

      // Update File Info
      if (this.filenameDisplay) this.filenameDisplay.textContent = meta.name;
      if (this.filesizeDisplay) {
        this.filesizeDisplay.textContent = `${meta.formattedSize} • ${meta.pageCount} total pages`;
      }

      // Hide upload zone, show file info & workspace
      if (this.uploadSection) this.uploadSection.style.display = "none";
      if (this.fileInfoCard) this.fileInfoCard.style.display = "flex";
      if (this.workspaceSection) this.workspaceSection.style.display = "block";
      if (this.resultSection) this.resultSection.style.display = "none";

      // Set initial range input value
      this.syncRangeInputFromSelection();

      // Load PDF.js document for canvas thumbnail generation
      if (window.pdfjsLib) {
        try {
          window.pdfjsLib.GlobalWorkerOptions.workerSrc =
            "https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js";
          const loadingTask = window.pdfjsLib.getDocument({
            data: meta.arrayBuffer.slice(0),
          });
          this.pdfJsDoc = await loadingTask.promise;
        } catch (e) {
          this.pdfJsDoc = null;
        }
      }

      this.renderPagesGrid();
      showExtractToast(
        `Loaded "${meta.name}" (${meta.pageCount} pages). Select pages to extract.`,
        "success",
        "PDF Ready",
      );
    } catch (err) {
      console.error("[ExtractPdf] Load error:", err);
      showExtractToast(
        err.message || "Could not parse PDF file.",
        "error",
        "Parse Error",
      );
    }
  }

  applyRangeInput() {
    if (!this.rangeInput || !this.pdfMeta) return;

    const val = this.rangeInput.value.trim();
    if (!val) {
      this.pages.forEach((p) => (p.selectedForExtract = false));
      this.renderPagesGrid(false);
      return;
    }

    try {
      const selectedIndices = ExtractPdfEngine.parsePageRange(
        val,
        this.pdfMeta.pageCount,
      );
      const selSet = new Set(selectedIndices);

      this.pages.forEach((p) => {
        p.selectedForExtract = selSet.has(p.index);
      });

      this.renderPagesGrid(false); // Don't overwrite range input during sync
      showExtractToast(
        `Applied range "${val}" (${selectedIndices.length} pages selected)`,
        "info",
        "Range Applied",
      );
    } catch (err) {
      showExtractToast(
        err.message || "Invalid page range.",
        "error",
        "Invalid Range",
      );
    }
  }

  syncRangeInputFromSelection() {
    if (!this.rangeInput) return;
    const selectedIndices = this.pages
      .filter((p) => p.selectedForExtract)
      .map((p) => p.index);

    this.rangeInput.value =
      ExtractPdfEngine.formatIndicesToRange(selectedIndices);
  }

  renderPagesGrid(updateRangeInput = true) {
    if (!this.pagesGrid) return;

    if (updateRangeInput) {
      this.syncRangeInputFromSelection();
    }

    this.pagesGrid.innerHTML = this.pages
      .map((p, idx) => {
        const isSel = p.selectedForExtract;

        const cardBorder = isSel
          ? "2px solid var(--primary)"
          : "2px solid var(--border-subtle)";
        const cardBg = isSel ? "rgba(99, 102, 241, 0.06)" : "var(--bg-surface)";
        const pageTextColor = isSel ? "var(--primary)" : "var(--text-main)";

        return `
        <div class="card extract-page-card"
             data-index="${idx}"
             style="position: relative; padding: 10px; border: ${cardBorder}; border-radius: var(--radius-lg); background: ${cardBg}; cursor: pointer; transition: all 0.15s ease; user-select: none;">

          <!-- Header -->
          <div style="display: flex; align-items: center; justify-content: space-between; margin-bottom: 6px;">
            <label style="display: flex; align-items: center; gap: 6px; cursor: pointer;" onclick="event.stopPropagation();">
              <input type="checkbox" class="extract-page-checkbox" data-index="${idx}" ${isSel ? "checked" : ""} style="width: 16px; height: 16px; cursor: pointer;" />
              <span style="font-size: 0.82rem; font-weight: 700; color: ${pageTextColor};">
                Page ${p.pageNum}
              </span>
            </label>
            ${isSel ? '<span class="badge badge--primary" style="font-size: 0.68rem; font-weight: 700; padding: 2px 6px; border-radius: 4px;">EXTRACT</span>' : ""}
          </div>

          <!-- Thumbnail Canvas Box -->
          <div style="position: relative; width: 100%; height: 160px; background: var(--bg-surface-hover); border: 1px solid var(--border-subtle); border-radius: var(--radius-md); display: flex; align-items: center; justify-content: center; overflow: hidden;">
            <canvas id="extract-canvas-${p.pageNum}" style="max-width: 100%; max-height: 100%; display: block;"></canvas>

            ${
              isSel
                ? `
              <div style="position: absolute; top: 6px; right: 6px; width: 26px; height: 26px; border-radius: 50%; background: var(--primary); color: #ffffff; display: flex; align-items: center; justify-content: center; font-weight: 800; font-size: 0.85rem; box-shadow: 0 2px 6px rgba(0,0,0,0.2);">
                ✓
              </div>
            `
                : ""
            }
          </div>

        </div>
      `;
      })
      .join("");

    this.bindGridEvents();
    this.renderThumbnails();
    this.updateSelectionSummary();
  }

  bindGridEvents() {
    if (!this.pagesGrid) return;

    // Card click toggles page extraction selection
    const cards = this.pagesGrid.querySelectorAll(".extract-page-card");
    cards.forEach((card) => {
      card.addEventListener("click", (e) => {
        const idx = parseInt(card.getAttribute("data-index"), 10);
        if (!isNaN(idx) && this.pages[idx]) {
          this.pages[idx].selectedForExtract =
            !this.pages[idx].selectedForExtract;
          this.renderPagesGrid(true);
        }
      });
    });

    // Checkbox click
    const checkboxes = this.pagesGrid.querySelectorAll(
      ".extract-page-checkbox",
    );
    checkboxes.forEach((cb) => {
      cb.addEventListener("change", (e) => {
        e.stopPropagation();
        const idx = parseInt(cb.getAttribute("data-index"), 10);
        if (!isNaN(idx) && this.pages[idx]) {
          this.pages[idx].selectedForExtract = cb.checked;
          this.renderPagesGrid(true);
        }
      });
    });
  }

  async renderThumbnails() {
    if (!this.pdfJsDoc) return;

    for (let i = 0; i < this.pages.length; i++) {
      const p = this.pages[i];
      const canvas = document.getElementById(`extract-canvas-${p.pageNum}`);
      if (!canvas) continue;

      try {
        const page = await this.pdfJsDoc.getPage(p.pageNum);
        const viewport = page.getViewport({ scale: 0.35 });

        canvas.width = viewport.width;
        canvas.height = viewport.height;
        const ctx = canvas.getContext("2d");

        await page.render({
          canvasContext: ctx,
          viewport: viewport,
        }).promise;
      } catch (err) {}
    }
  }

  updateSelectionSummary() {
    const selectedCount = this.pages.filter((p) => p.selectedForExtract).length;
    const total = this.pages.length;

    if (this.selectionBadge) {
      this.selectionBadge.textContent = `${selectedCount} of ${total} pages selected to extract`;
    }
  }

  selectAll() {
    this.pages.forEach((p) => (p.selectedForExtract = true));
    this.renderPagesGrid(true);
  }

  deselectAll() {
    this.pages.forEach((p) => (p.selectedForExtract = false));
    this.renderPagesGrid(true);
  }

  async executeExtract() {
    if (!this.currentFile || !this.arrayBuffer) {
      showExtractToast(
        "Please upload a PDF file first.",
        "warning",
        "No PDF Loaded",
      );
      return;
    }

    const selectedIndices = this.pages
      .filter((p) => p.selectedForExtract)
      .map((p) => p.index);

    if (selectedIndices.length === 0) {
      showExtractToast(
        "Please click on at least one page or enter a page range to select pages for extraction.",
        "error",
        "No Pages Selected",
      );
      return;
    }

    // UI state: Processing
    if (this.workspaceSection) this.workspaceSection.style.display = "none";
    if (this.processingState) this.processingState.style.display = "block";
    if (this.progressBar) this.progressBar.style.width = "30%";

    try {
      if (this.createdBlobUrl) {
        URL.revokeObjectURL(this.createdBlobUrl);
        this.createdBlobUrl = null;
      }

      const result = await this.engine.extractPages(
        this.currentFile,
        this.arrayBuffer,
        selectedIndices,
        (percent) => {
          if (this.progressBar) this.progressBar.style.width = `${percent}%`;
        },
      );

      this.createdBlobUrl = result.url;

      // Update Result UI
      if (this.resultSummary) {
        this.resultSummary.textContent = `Successfully extracted ${result.extractedCount} ${result.extractedCount === 1 ? "page" : "pages"} from "${this.currentFile.name}". New file size is ${result.formattedSize}.`;
      }

      if (this.btnDownloadPdf) {
        this.btnDownloadPdf.href = result.url;
        this.btnDownloadPdf.download = result.filename;
      }

      if (this.processingState) this.processingState.style.display = "none";
      if (this.resultSection) this.resultSection.style.display = "block";

      showExtractToast(
        `Extracted ${result.extractedCount} ${result.extractedCount === 1 ? "page" : "pages"} successfully!`,
        "success",
        "Extraction Complete",
      );
    } catch (err) {
      console.error("[ExtractPdf] Execute error:", err);
      if (this.processingState) this.processingState.style.display = "none";
      if (this.workspaceSection) this.workspaceSection.style.display = "block";
      showExtractToast(
        err.message || "An error occurred while extracting PDF pages.",
        "error",
        "Extraction Failed",
      );
    }
  }

  resetView() {
    if (this.resultSection) this.resultSection.style.display = "none";
    if (this.processingState) this.processingState.style.display = "none";

    if (this.currentFile) {
      if (this.workspaceSection) this.workspaceSection.style.display = "block";
    } else {
      if (this.fileInfoCard) this.fileInfoCard.style.display = "none";
      if (this.uploadSection) this.uploadSection.style.display = "block";
    }
  }
}

